"""Original expanded foundation packets; answers are kept separate from learner tasks."""
FOUNDATION=[
dict(id='FND-01',title='Entrar numa conversa e apresentar-se',
 targets=['Apresentação com I am','Identificação com this is','Nome como pergunta pronta','My e your'],
 words=['hello','name','first name','last name','nice to meet you','friend'],
 glossary='Welcome = boas-vindas; badge = crachá; first name = nome próprio; last name = sobrenome; this is = esta pessoa é. Não é necessário usar nome real.',
 readings=[('Recepção','WELCOME\nFirst name: Lia\nLast name: Costa\nHello. I’m Lia. This is my friend, Jo.'),('Duas apresentações','A: Hello. My name is Kim.\nB: Hi, Kim. I’m Sam.\nA: Nice to meet you, Sam.\nB: Nice to meet you too.')],
 audio='Host: Hello. What’s your name?\nGuest: My name is Lee.\nHost: Jo?\nGuest: No. Lee.\nHost: Lee. Nice to meet you.\nGuest: Nice to meet you.',
 understanding=[('Qual é o primeiro nome no cartão?','Lia.'),('Qual é o sobrenome?','Costa.'),('Quem Lia apresenta como friend?','Jo; não é necessariamente familiar.'),('Na segunda leitura, quem responde I’m Sam?','B.'),('Na escuta, o nome correto é Jo ou Lee?','Lee; Jo é a confirmação incorreta.'),('Que informação o anfitrião pede?','Nome: What’s your name?')],
 practice=[('Complete: I ___ Lia.','am.'),('Escolha para apresentar outra pessoa: I am Jo / This is Jo.','This is Jo.'),('Ordene: name / is / My / Kim.','My name is Kim.'),('Você pergunta o nome de Sam. Complete: What’s ___ name?','your.'),('Corrija: I Lee.','I am Lee / I’m Lee.'),('Qual acolhe uma pessoa recém-apresentada: Nice to meet you / What’s your name?','Nice to meet you.'),('Reescreva I am Kim com contração.','I’m Kim.'),('Complete a apresentação de um amigo: ___ is my friend Jo.','This.')],
 guided='Cartão A: nome Sol; amigo Kim. Cartão B: nome Lee; não conhece Sol. A cumprimenta, diz seu nome e pergunta o de B. B responde e pergunta quem é Kim. A pode apontar e usar This is my friend Kim. Em modo autônomo, grave apenas as falas de A, deixando espaço para responder como B depois.',
 model='A: Hello. I’m Sol. What’s your name?\nB: My name is Lee.\nA: Nice to meet you, Lee. This is my friend Kim.\nB: Hello, Kim.',
 independent='Novo cartão A: Alex; amigo Noa. B: Eva. Troquem nomes sem olhar o modelo. Preencha dois crachás e apresente Noa. O parceiro deve identificar qual nome pertence a quem.',
 key='Crachás Alex/Eva; Noa é a pessoa apresentada, não quem fala. Aceitar My name is e I’m, pausas e apoio visual.',
 review='Depois de outro encontro, apresente Mia a alguém que não a conhece e pergunte o nome do novo interlocutor. Compare com a primeira tentativa: ainda omite am/is?',
 phon='Destaque o nome na apresentação: I’m LEE. Peça ao ouvinte que repita o nome entendido. Não anglicizar nomes pessoais à força.',
 mediation='Ajude uma pessoa lusófona a identificar nome próprio e sobrenome no cartão de Lia; aponte os campos sem traduzir o nome.',
 teacher='Observe troca de I/My e this/I. Se a pessoa confundir quem fala, use cartões separados e aponte para falante e amigo antes de modelar. Não cobrar terminologia de pronomes.'),
dict(id='FND-02',title='Entender instruções e pedir reparo',
 targets=['Instruções simples','Pedidos de ajuda como blocos','Correção com yes e no'],
 words=['please','thank you','again','slowly','help','yes','no','listen','look','read','write','stop'],
 glossary='Read = leia; write = escreva; listen = escute; look = olhe; help = ajuda. Cada instrução pode ser demonstrada com gesto. Please acompanha pedidos; thank you agradece.',
 readings=[('Cartão de tarefa','1. Look: SAM.\n2. Read: SAM.\n3. Write: SAM.\n4. Stop.'),('Cartão de ajuda','Again, please.\nSlowly, please.\nI don’t understand.\nHelp, please.')],
 audio='Tutor: Listen. My name is Jo. Write Jo.\nLearner: Again, please.\nTutor: Write Jo.\nLearner: Kim?\nTutor: No. Jo.\nLearner: Jo. Thank you.\nTutor: Yes. Stop.',
 understanding=[('Que nome deve ser escrito no cartão?','Sam.'),('Qual instrução pede leitura?','Read.'),('Qual pede ajuda com ritmo?','Slowly, please.'),('O que deve acontecer depois de escrever?','Stop; parar.'),('Na escuta, qual nome deve ser escrito?','Jo; não Sam da leitura nem Kim da tentativa.'),('A primeira solicitação do aluno pede repetição ou silêncio?','Repetição: Again, please.')],
 practice=[('Relacione Listen: escrever/escutar.','Escutar.'),('Relacione Look: olhar/parar.','Olhar.'),('Complete: Again, ___.','please.'),('Uma pessoa diz Lee, mas seu cartão tem Kim. Corrija com No.','No. Kim.'),('Você não entendeu. Escolha I don’t understand / Nice to meet you.','I don’t understand.'),('Ordene: please / Slowly.','Slowly, please.'),('Agradeça depois de receber ajuda.','Thank you.'),('Peça que a pessoa escreva Mia usando Write.','Write Mia, please.')],
 guided='A recebe cartão “Write Lee”. B não vê e pede repetição antes de escrever. A repete sem gritar; B confirma Lee? A diz Yes ou corrige se necessário. Troquem os papéis e usem Sol.',
 model='A: Write Lee, please.\nB: Again, please.\nA: Write Lee.\nB: Lee?\nA: Yes.\nB: Thank you.',
 independent='A recebe “Read EVA; write EVA; stop”. B ouve sem ver, pede ajuda quando precisar e produz o nome. Depois B pede a A que escreva Noa. Guardem os dois resultados.',
 key='Primeira rodada Eva; segunda Noa. A expressão de ajuda deve servir à dificuldade. Aceitar repetir só o nome para confirmar. Não confundir silêncio com compreensão.',
 review='No encontro seguinte, dê “Write Ben” sem mostrar o cartão. Verifique se o aluno pede repetição quando necessário e registra Ben, sem copiar nomes antigos.',
 phon='Compare WRITE e READ pela forma sonora, sem pronunciar w em write. A pessoa de apoio lê cada palavra; o aluno aponta a ação. Sem áudio, registrar somente associação escrita.',
 mediation='Explique em português a alguém o que deve fazer em “Look; write Sam; stop”. Conservar ordem e nome.',
 teacher='Se houver dificuldade de escrita, permitir selecionar letras ou apontar nome antes de copiar. Registrar a adaptação; não concluir falta de compreensão oral a partir de escrita lenta.'),
dict(id='FND-03',title='Conferir nome, código e origem',
 targets=['Origem e localização','Correção com yes e no','Nome como pergunta pronta'],
 words=['first name','last name','from','in','code','spell'],
 glossary='Brazil = Brasil; Canada = Canadá. Números: zero, one, two, three, four, five, six, seven, eight, nine. How do you spell it? = como se soletra? Consulte o [alfabeto com apoio](../../../../english/units/EN-PRE-A1-03.md). Peça que alguém diga as letras antes de soletrar; a tabela escrita não substitui escuta. Não exigir IPA.',
 readings=[('Ficha A','Name: Mia\nFrom: Brazil\nIn: Recife\nCode: 407'),('Ficha B','Name: Leo\nFrom: Canada\nIn: Natal\nCode: 208')],
 audio='Host: What’s your name?\nGuest: Leo. L, E, O.\nHost: Code two, zero, nine?\nGuest: No. Two, zero, eight.\nHost: Where are you from?\nGuest: I’m from Canada. I’m in Natal.',
 understanding=[('Qual código pertence a Mia?','407.'),('Mia está no Canadá?','Não; está em Recife e é do Brasil.'),('Qual pessoa está em Natal?','Leo.'),('Qual é a origem de Leo?','Canada.'),('Na escuta, qual dígito é corrigido?','O último: nine muda para eight.'),('Quais letras compõem o nome ouvido?','L, E, O.')],
 practice=[('Escreva two zero eight em dígitos.','208.'),('Escreva 407 em palavras separadas.','four zero seven.'),('Complete para origem: I’m ___ Brazil.','from.'),('Complete para localização: I’m ___ Natal.','in.'),('Seu código é305; alguém confirma309. Corrija.','No. Three, zero, five.'),('Qual pergunta pede letras: How do you spell it? / Where are you from?','How do you spell it?'),('Ordene: Canada / from / I’m.','I’m from Canada.'),('Explique diferença entre from Brazil e in Brazil.','Origem no Brasil versus localização no Brasil.')],
 guided='A: Noa, from Brazil, in Belém, código614. B recebe apenas os campos vazios e faz perguntas. B confirma intencionalmente código641; A corrige. Invertam com Eva, from Canada, in Recife, código502.',
 model='B: What’s your name?\nA: Noa. N, O, A.\nB: Code six, four, one?\nA: No. Six, one, four.\nB: Where are you from?\nA: I’m from Brazil. I’m in Belém.',
 independent='Cartão novo: Sam, from Brazil, in Toronto, código850. B coleta os três dados e soletra o nome com apoio. A não deve confundir localização em Toronto com origem no Canadá.',
 key='Sam/S-A-M; origem Brazil; localização Toronto;850. Não avaliar conhecimento geográfico que não foi pedido: os campos bastam.',
 review='Depois de uma semana, ouvir código709 e corrigir transcrição790. Usar novo nome de três letras escolhido pelo aluno.',
 phon='Compare nomes de E e I em inglês com ajuda sonora. Depois peça ao parceiro que restitua o código em dígitos para verificar compreensão, não sotaque.',
 mediation='Passe origem, localização e código de Leo para pessoa lusófona, mantendo a ordem dos dígitos. Dados são fictícios.',
 teacher='O objetivo é transmitir informações com recursos de reparo. Permitir consulta ao alfabeto; a falta de memorização de26nomes de letras não bloqueia toda a unidade.'),
dict(id='FND-04',title='Identificar objetos e pertencimento',
 targets=['Identificação com this is','A e an em objetos','Plural regular inicial','My e your'],
 words=['book','pen','bag','phone','chair','table','apple','friend'],
 glossary='One = um; two = dois; three = três; four = quatro. This is = isto/esta pessoa é. My = meu/minha; your = seu/sua. No exemplo, an apple começa com som vocálico.',
 readings=[('Mesa de Lia','Lia: a bag, a phone, two books.\nThis is my bag. This is my phone.'),('Mesa de Jo','Jo: an apple, a pen, three books.\nThis is my pen. This is my apple.')],
 audio='Host: Is this your bag, Jo?\nJo: No. My pen.\nHost: This pen?\nJo: Yes, thank you.\nHost: Two books?\nJo: No. Three books.',
 understanding=[('Quantos livros aparecem na mesa de Lia?','Dois.'),('Quem tem uma maçã no cartão?','Jo.'),('Qual pessoa tem um telefone listado?','Lia.'),('A/an muda porque o objeto é de Lia ou Jo?','Não; depende do som inicial no exemplo.'),('Na escuta, Jo confirma a bolsa?','Não; pede/identifica sua caneta.'),('Quantos livros Jo confirma?','Três.')],
 practice=[('Complete: ___ apple. (a/an)','an.'),('Complete: ___ book. (a/an)','a.'),('Escreva plural de pen após four.','four pens.'),('Corrija: two book.','two books.'),('Pergunte se a bolsa é da outra pessoa: Is this ___ bag?','your.'),('Apresente seu telefone: This is ___ phone.','my.'),('Ordene: is / my / This / pen.','This is my pen.'),('Qual é uma pessoa no vocabulário: friend/table?','friend.')],
 guided='A tem cartão com bag e two pens; B tem phone e three books. Sem mostrar o cartão, cada pessoa identifica seus objetos. Introduza troca: A aponta phone e diz My phone; B deve corrigir No, my phone.',
 model='A: This is my bag. Two pens.\nB: This is my phone. Three books.\nA: Your phone?\nB: Yes. My phone.',
 independent='Cartão de Kim: an apple, four pens, a bag. Cartão de Lee: a phone, two books. Escreva etiquetas e resolva uma troca de objeto. O ouvinte confere quantidades.',
 key='Kim: an apple/four pens/a bag; Lee: a phone/two books. A/an e plural devem ajudar a identificar os itens; aceitar apoio visual e mensagens curtas.',
 review='Use um novo conjunto de objetos desenhados e peça identificação sem consultar os nomes antigos. Retome apenas os itens não recuperados.',
 phon='Compare book/books e pen/pens com leitura por parceiro. O ouvinte registra se ouviu um ou mais de um; não depender só do número antes do nome.',
 mediation='Explique a uma pessoa lusófona quais objetos pertencem a Kim, sem atribuir o telefone a ela.',
 teacher='Se aluno usar concordância de gênero em my, compare my pen e my bag. Para plural, comece por uma única oposição antes de incluir três objetos diferentes.'),
dict(id='FND-05',title='Fazer pedido e conferir o preço',
 targets=['Número e pedido','Correção com yes e no','A e an em objetos'],
 words=['water','tea','coffee','apple','bread','please','thank you','how much'],
 glossary='Menu = cardápio; credits = créditos fictícios; one/two/three/four/five/six =1–6. Bread e water são apresentados como alimento/bebida; a tea/a coffee podem pedir porção.',
 readings=[('Menu A','Water: 2 credits\nTea: 3 credits\nCoffee: 4 credits\nApple: 1 credit'),('Pedido escrito','One tea, please.\nOne apple, please.\nTea: 3. Apple: 1. Total: 4 credits.')],
 audio='Customer: One coffee, please.\nServer: Tea?\nCustomer: No. Coffee, please.\nServer: Four credits.\nCustomer: Four?\nServer: Yes.\nCustomer: Thank you.',
 understanding=[('Quanto custa water?','2 créditos.'),('Qual produto custa3?','Tea.'),('Quantos produtos diferentes há no pedido escrito?','Dois: tea e apple.'),('Qual o total do pedido escrito?','4 créditos;3+1.'),('Na escuta, qual produto foi corrigido?','Tea foi corrigido para coffee.'),('Qual preço foi confirmado na escuta?','4 créditos.')],
 practice=[('Peça água com please.','Water, please / One water, please, como porção.'),('Peça duas maçãs.','Two apples, please.'),('Pergunte o preço com How much.','How much? / How much is it?'),('Complete: One coffee, ___.','please.'),('Corrija pedido de chá se você quer café.','No. Coffee, please.'),('MenuA: água2 e maçã1. Qual total?','3 créditos.'),('Complete: ___ apple, please.','An / One, conforme construção.'),('Agradeça após confirmação.','Thank you.')],
 guided='A atende com MenuA. B quer tea e apple e tem4créditos. B pede, confirma total e agradece. Nova rodada: B tem3créditos e quer coffee. A informa4; B pode escolher tea sem fingir orçamento maior.',
 model='B: One tea and one apple, please.\nA: Four credits.\nB: Four?\nA: Yes.\nB: Thank you.',
 independent='MenuB: water3, tea5, coffee6, apple2. Com5créditos, peça water e apple. Depois ouça confirmação incorreta de6 e corrija para5.',
 key='Water3 + apple2 =5. O novo menu substitui os preços antigos. Não aceitar total4 copiado do modelo.',
 review='Mude o preço de water para4 e apple para1. Peça os dois e confira total5; depois peça somente água para distinguir quantidade de preço.',
 phon='Trabalhe TEA e COFfee, depois FOUR e FIVE. O ouvinte restitui produto e preço separadamente. Mostrar dígito é reparo legítimo.',
 mediation='Ajude pessoa lusófona que quer água e maçã: informe os nomes no MenuB e total5. Não traduzir preço de outro menu.',
 teacher='Não transformar erro de soma em diagnóstico de língua. Permitir cálculo visual. Registrar separadamente reconhecimento de preço, pedido e cálculo.'),
dict(id='FND-06',title='Participar de um encontro e atualizar a agenda',
 targets=['Dia e hora em blocos','Origem e localização','Pedidos de ajuda como blocos','Número e pedido'],
 words=['today','Monday','Friday','at ten','room','here','code','name'],
 glossary='Days: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday. Horas: nine9, ten10, eleven11, twelve12. Morning = manhã. Agenda deste exercício usa manhã; não deduzir automaticamente em outros contextos.',
 readings=[('Convite inicial','WELCOME\nMonday, 10:00 in the morning\nRoom 2\nBring a pen. (Traga uma caneta.)'),('Ficha de visitante','Name: Eva\nFrom: Canada\nIn: Recife\nCode: 306\nTea: 3 credits')],
 audio='Host: English on Monday. At eleven, not ten. Room four.\nEva: Again, please.\nHost: Monday. At eleven. Room four.\nEva: Monday, at eleven, room four.\nHost: Yes.',
 understanding=[('Qual hora está no convite inicial?','10h da manhã.'),('Qual objeto levar?','Uma caneta.'),('Qual é a origem de Eva?','Canada; localização é Recife.'),('Qual é o código de Eva?','306.'),('Na escuta, qual é a nova hora?','11h da manhã.'),('Na escuta, qual é a nova sala?','4; não2 do convite antigo.')],
 practice=[('Complete: ___ Monday.','On.'),('Complete: ___ eleven.','At.'),('Corrija Room2 quando a informação nova é Room4.','No. Room four.'),('Escreva306 em palavras separadas.','three zero six.'),('Complete para localização: Eva is ___ Recife.','in; aceitar I’m in Recife quando fala como Eva.'),('Peça repetição de horário.','Again, please.'),('Peça chá com cortesia.','One tea, please.'),('Registre compromisso atualizado em português.','Segunda,11h da manhã,sala4.')],
 guided='A é recepção e vê mudança de segunda10h/sala2 para segunda11h/sala4. B vê só convite antigo. B deve obter mudança, confirmar dados e preencher agenda. Depois B se apresenta como Eva e pede chá.',
 model='B: Hello. I’m Eva. Room two, at ten?\nA: No. Room four, at eleven.\nB: Again, please.\nA: Monday, at eleven, room four.\nB: Thank you. One tea, please.',
 independent='Novo encontro: Friday,9h da manhã,Room5; visitante Lee,from Brazil,in Natal,código817. Atualização oral: Friday,10h da manhã,Room6. Registre somente compromisso final e faça pedido de água de2créditos.',
 key='NomeLee; origemBrazil; localizaçãoNatal; código817; sexta10h,sala6; água2. Cartão de origem não muda com atualização de evento. Aceitar frases curtas apoiadas; observar reparo.',
 review='Uma semana depois, usar Tuesday,12h,Room3 e visitante Kim. Pedir confirmação e introduzir troca de sala para7. Não reutilizar toda a história de Eva.',
 phon='Pausar entre DAY / TIME / ROOM. Peça ao ouvinte que registre cada campo; se um falhar, repetir apenas esse dado e confirmar.',
 mediation='Explique a alguém lusófono a alteração de horário e sala, distinguindo convite antigo e informação atual.',
 teacher='Esta integração amostra várias funções, mas não certifica nível. Se falhar um campo, localizar se foi leitura, escuta, memória de trabalho ou produção; oferecer apoio e registrar nova tentativa.')
]
